/**
 * ============================================================
 * FINESTYLE FRAMEWORK v3.0 — CORE ENGINE
 * by John Rish Ladica
 * Built on 2.x architecture, redesigned for 3.0
 * ============================================================
 *
 * Exports: window.FineStyle
 * 
 * MODULES:
 *   FineStyle.Store         — Reactive state management
 *   FineStyle.Commands      — Command palette system
 *   FineStyle.Modal         — Modal dialogs
 *   FineStyle.Toast         — Toast notifications
 *   FineStyle.Drawer        — Slide-over drawers
 *   FineStyle.Dropdown      — Dropdown menus
 *   FineStyle.Accordion     — Accordion panels
 *   FineStyle.Tabs          — Tab navigation
 *   FineStyle.Tooltip       — Tooltips
 *   FineStyle.Table         — Sortable/filterable tables
 *   FineStyle.Chart         — Data visualization wrappers
 *   FineStyle.Terminal      — Terminal interface
 *   FineStyle.ContextMenu   — Context menus
 *   FineStyle.LoadingState  — Loading overlays
 *   FineStyle.Form          — Form validation
 *   FineStyle.Animate       — Animation utilities
 *   FineStyle.Theme         — Theme management
 *   FineStyle.Events        — Event bus
 *   FineStyle.utils         — Core utilities
 */

const FineStyle = (() => {
  'use strict';

  // ============================================================
  // CORE UTILITIES
  // ============================================================
  const utils = {
    debounce(fn, wait = 250) {
      let t;
      return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), wait); };
    },
    throttle(fn, limit = 100) {
      let last = 0;
      return (...args) => {
        const now = Date.now();
        if (now - last >= limit) { last = now; fn(...args); }
      };
    },
    qs: (sel, ctx = document) => ctx.querySelector(sel),
    qsa: (sel, ctx = document) => [...ctx.querySelectorAll(sel)],
    el(tag, props = {}, children = []) {
      const e = document.createElement(tag);
      Object.entries(props).forEach(([k, v]) => {
        if (k === 'class') e.className = v;
        else if (k === 'html') e.innerHTML = v;
        else if (k === 'text') e.textContent = v;
        else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);
        else e.setAttribute(k, v);
      });
      children.forEach(c => c && e.append(typeof c === 'string' ? document.createTextNode(c) : c));
      return e;
    },
    uid: () => Math.random().toString(36).slice(2, 9),
    clamp: (v, min, max) => Math.min(Math.max(v, min), max),
    lerp: (a, b, t) => a + (b - a) * t,
    formatNumber: (n, opts = {}) => new Intl.NumberFormat(undefined, opts).format(n),
    formatDate: (d, opts = {}) => new Intl.DateTimeFormat(undefined, opts).format(new Date(d)),
    deepMerge: (target, source) => {
      const out = { ...target };
      for (const key in source) {
        out[key] = (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key]))
          ? utils.deepMerge(target[key] || {}, source[key])
          : source[key];
      }
      return out;
    },
    pick: (obj, keys) => Object.fromEntries(keys.map(k => [k, obj[k]])),
    escapeHTML: str => str.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
    copyToClipboard: async text => {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        const ta = document.createElement('textarea');
        ta.value = text;
        Object.assign(ta.style, { position: 'fixed', opacity: '0' });
        document.body.append(ta);
        ta.select();
        const ok = document.execCommand('copy');
        ta.remove();
        return ok;
      }
    },
    isMobile: () => window.matchMedia('(max-width: 768px)').matches,
    isReduced: () => window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    getCSSVar: (name, el = document.documentElement) => getComputedStyle(el).getPropertyValue(name).trim(),
    setCSSVar: (name, val, el = document.documentElement) => el.style.setProperty(name, val),
  };

  // ============================================================
  // EVENT BUS
  // ============================================================
  const Events = (() => {
    const listeners = new Map();
    return {
      on(event, fn) {
        if (!listeners.has(event)) listeners.set(event, new Set());
        listeners.get(event).add(fn);
        return () => this.off(event, fn);
      },
      off(event, fn) { listeners.get(event)?.delete(fn); },
      emit(event, data) { listeners.get(event)?.forEach(fn => fn(data)); },
      once(event, fn) {
        const wrapper = data => { fn(data); this.off(event, wrapper); };
        return this.on(event, wrapper);
      },
    };
  })();

  // ============================================================
  // REACTIVE STATE STORE
  // ============================================================
  class Store {
    #state;
    #listeners = new Map();

    constructor(initial = {}) {
      this.#state = { ...initial };
      this.proxy = new Proxy(this.#state, {
        set: (target, key, value) => {
          const prev = target[key];
          target[key] = value;
          if (prev !== value) this.#notify(key, value, prev);
          return true;
        },
        get: (target, key) => target[key],
      });
    }

    get(key) { return this.#state[key]; }

    set(key, value) {
      this.proxy[key] = value;
      return this;
    }

    update(partial) {
      Object.entries(partial).forEach(([k, v]) => this.set(k, v));
      return this;
    }

    subscribe(key, fn) {
      if (!this.#listeners.has(key)) this.#listeners.set(key, new Set());
      this.#listeners.get(key).add(fn);
      return () => this.#listeners.get(key)?.delete(fn);
    }

    #notify(key, value, prev) {
      this.#listeners.get(key)?.forEach(fn => fn(value, prev));
      Events.emit(`store:${key}`, { value, prev });
    }

    snapshot() { return { ...this.#state }; }
  }

  // App-level store
  const AppStore = new Store({
    theme: (typeof localStorage !== 'undefined' && localStorage.getItem('fs-theme')) || 'dark',
    sideNavOpen: false,
    commandPaletteOpen: false,
  });

  // Theme management
  const Theme = {
    apply(theme) {
      document.documentElement.setAttribute('data-theme', theme);
      if (typeof localStorage !== 'undefined') localStorage.setItem('fs-theme', theme);
      AppStore.set('theme', theme);
      Events.emit('theme:change', { theme });
      document.dispatchEvent(new CustomEvent('fs-theme-change', { detail: { theme } }));
    },
    get current() { return AppStore.get('theme'); },
    toggle() { this.apply(this.current === 'dark' ? 'light' : 'dark'); },
    set(theme) { this.apply(theme); },
    isDark() { return this.current === 'dark'; },
  };

  // Initialize theme
  Theme.apply(AppStore.get('theme'));

  // ============================================================
  // ANIMATION ENGINE
  // ============================================================
  const Animate = {
    _prefix: 'fs-animate-',
    _map: {
      'fade-in': 'fade-in', 'slide-in': 'slide-in', 'zoom-in': 'zoom-in',
      'float': 'float', 'fade-in-up': 'fade-in-up', 'fade-in-down': 'fade-in-down',
      'fade-in-left': 'fade-in-left', 'fade-in-right': 'fade-in-right',
    },
    run(element, type, opts = {}) {
      if (utils.isReduced()) return;
      const el = typeof element === 'string' ? utils.qs(element) : element;
      if (!el) return;
      const cls = this._prefix + (this._map[type] || type);
      el.classList.remove(cls);
      void el.offsetWidth; // reflow
      el.classList.add(cls);
      if (opts.duration) el.style.animationDuration = opts.duration;
      if (opts.delay) el.style.animationDelay = opts.delay;
      if (opts.fill) el.style.animationFillMode = opts.fill;
      if (opts.onEnd) el.addEventListener('animationend', opts.onEnd, { once: true });
      return el;
    },
    stagger(elements, type, opts = {}) {
      const els = typeof elements === 'string' ? utils.qsa(elements) : [...elements];
      const delay = opts.stagger || 80;
      els.forEach((el, i) => {
        setTimeout(() => this.run(el, type, opts), i * delay);
      });
    },
    scrollReveal(selector = '.animate-on-scroll', opts = {}) {
      const els = utils.qsa(selector);
      const io = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            if (opts.once !== false) io.unobserve(entry.target);
          } else if (opts.once === false) {
            entry.target.classList.remove('visible');
          }
        });
      }, { threshold: opts.threshold || 0.1, rootMargin: opts.rootMargin || '0px' });
      els.forEach(el => io.observe(el));
      return io;
    },
  };

  // Compat alias
  const animate = (el, type, opts) => Animate.run(el, type, opts);

  // ============================================================
  // MODAL SYSTEM
  // ============================================================
  class Modal {
    #el;
    #opts;

    constructor(content, opts = {}) {
      this.#opts = {
        title: 'Dialog',
        closable: true,
        size: '',
        footer: null,
        onOpen: null,
        onClose: null,
        ...opts,
      };
      this.#build(content);
    }

    #build(content) {
      const { title, closable, size, footer } = this.#opts;
      this.#el = utils.el('div', { class: `fs-modal${size ? ' fs-modal-' + size : ''}`, role: 'dialog', 'aria-modal': 'true' });
      this.#el.innerHTML = `
        <div class="fs-modal-content">
          <div class="fs-modal-header">
            <h3 class="fs-modal-title">${utils.escapeHTML(title)}</h3>
            ${closable ? '<button class="fs-modal-close" aria-label="Close">&times;</button>' : ''}
          </div>
          <div class="fs-modal-body">${content}</div>
          ${footer ? `<div class="fs-modal-footer">${footer}</div>` : ''}
        </div>`;

      if (closable) {
        this.#el.querySelector('.fs-modal-close')?.addEventListener('click', () => this.close());
        this.#el.addEventListener('click', e => { if (e.target === this.#el) this.close(); });
      }

      document.addEventListener('keydown', e => { if (e.key === 'Escape' && closable) this.close(); }, { once: true });
      document.body.append(this.#el);
    }

    show() {
      requestAnimationFrame(() => this.#el.classList.add('active'));
      document.body.style.overflow = 'hidden';
      this.#opts.onOpen?.();
      Events.emit('modal:open', { modal: this });
      return this;
    }

    close() {
      this.#el.classList.remove('active');
      document.body.style.overflow = '';
      this.#opts.onClose?.();
      Events.emit('modal:close', { modal: this });
      setTimeout(() => this.#el.remove(), 320);
    }

    update(content) {
      const body = this.#el.querySelector('.fs-modal-body');
      if (body) body.innerHTML = content;
      return this;
    }

    static confirm(message, opts = {}) {
      return new Promise(resolve => {
        const modal = new Modal(`<p>${utils.escapeHTML(message)}</p>`, {
          title: opts.title || 'Confirm',
          footer: `
            <button class="fs-btn fs-btn-ghost fs-btn-sm" id="fs-confirm-cancel">${opts.cancelText || 'Cancel'}</button>
            <button class="fs-btn fs-btn-primary fs-btn-sm" id="fs-confirm-ok">${opts.okText || 'Confirm'}</button>`,
          closable: true,
          onClose: () => resolve(false),
        });
        modal.show();
        const el = modal.#el;
        el.querySelector('#fs-confirm-ok')?.addEventListener('click', () => { resolve(true); modal.close(); });
        el.querySelector('#fs-confirm-cancel')?.addEventListener('click', () => { resolve(false); modal.close(); });
      });
    }

    static alert(message, opts = {}) {
      const modal = new Modal(`<p>${utils.escapeHTML(message)}</p>`, {
        title: opts.title || 'Notice',
        footer: `<button class="fs-btn fs-btn-primary fs-btn-sm" id="fs-alert-ok">${opts.okText || 'OK'}</button>`,
      });
      modal.show();
      modal.#el.querySelector('#fs-alert-ok')?.addEventListener('click', () => modal.close());
      return modal;
    }
  }

  // ============================================================
  // TOAST NOTIFICATION SYSTEM
  // ============================================================
  const Toast = (() => {
    let container;

    const icons = {
      success: '✓',
      warning: '⚠',
      error: '✕',
      info: 'ℹ',
    };

    function ensureContainer() {
      if (!container || !document.body.contains(container)) {
        container = utils.el('div', { class: 'fs-toast-container', role: 'region', 'aria-label': 'Notifications' });
        document.body.append(container);
      }
    }

    function show(message, type = 'info', opts = {}) {
      ensureContainer();
      const duration = opts.duration ?? 4000;
      const title = opts.title ?? type.charAt(0).toUpperCase() + type.slice(1);

      const toast = utils.el('div', {
        class: `fs-toast ${type}`,
        role: 'alert',
        'aria-live': 'polite',
      });
      toast.innerHTML = `
        <span class="fs-toast-icon">${icons[type] || 'ℹ'}</span>
        <div class="fs-toast-body">
          <div class="fs-toast-title">${utils.escapeHTML(title)}</div>
          <div class="fs-toast-message">${utils.escapeHTML(message)}</div>
        </div>
        <button class="fs-toast-close" aria-label="Dismiss">&times;</button>`;

      container.append(toast);
      requestAnimationFrame(() => toast.classList.add('show'));

      const dismiss = () => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 350);
      };

      toast.querySelector('.fs-toast-close')?.addEventListener('click', dismiss);
      if (duration > 0) setTimeout(dismiss, duration);

      Events.emit('toast:show', { message, type });
      return { dismiss };
    }

    return {
      show,
      success: (msg, opts) => show(msg, 'success', opts),
      warning: (msg, opts) => show(msg, 'warning', opts),
      error:   (msg, opts) => show(msg, 'error', opts),
      info:    (msg, opts) => show(msg, 'info', opts),
    };
  })();

  // ============================================================
  // DROPDOWN SYSTEM
  // ============================================================
  const Dropdown = (() => {
    let active = null;

    function close() {
      if (active) {
        active.classList.remove('open');
        active.closest('.fs-dropdown')?.classList.remove('open');
        active = null;
      }
    }

    function toggle(trigger) {
      const dropdown = trigger.closest('.fs-dropdown');
      const menu = dropdown?.querySelector('.fs-dropdown-menu');
      if (!menu) return;
      if (active === menu) return close();
      close();
      menu.classList.add('open');
      dropdown.classList.add('open');
      active = menu;
    }

    function init() {
      document.addEventListener('click', e => {
        const trigger = e.target.closest('[data-dropdown]') || e.target.closest('.fs-dropdown-trigger');
        if (trigger) { e.preventDefault(); toggle(trigger); return; }
        if (!e.target.closest('.fs-dropdown')) close();
      });
      document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    }

    return { toggle, close, init };
  })();

  // ============================================================
  // ACCORDION SYSTEM
  // ============================================================
  const Accordion = (() => {
    function open(trigger) {
      const item = trigger.closest('.fs-accordion-item');
      const content = item?.querySelector('.fs-accordion-content');
      if (!content) return;
      trigger.classList.add('open');
      content.classList.add('open');
      content.style.maxHeight = content.scrollHeight + 'px';
      Events.emit('accordion:open', { trigger });
    }

    function close(trigger) {
      const item = trigger.closest('.fs-accordion-item');
      const content = item?.querySelector('.fs-accordion-content');
      if (!content) return;
      trigger.classList.remove('open');
      content.classList.remove('open');
      content.style.maxHeight = '0';
      Events.emit('accordion:close', { trigger });
    }

    function toggle(trigger, exclusive = false) {
      const isOpen = trigger.classList.contains('open');
      if (exclusive) {
        const accordion = trigger.closest('.fs-accordion');
        accordion?.querySelectorAll('.fs-accordion-trigger').forEach(t => close(t));
      }
      isOpen ? close(trigger) : open(trigger);
    }

    function init() {
      document.addEventListener('click', e => {
        const trigger = e.target.closest('.fs-accordion-trigger');
        if (trigger) toggle(trigger, trigger.closest('.fs-accordion')?.hasAttribute('data-exclusive'));
      });
    }

    return { open, close, toggle, init };
  })();

  // ============================================================
  // TAB SYSTEM
  // ============================================================
  const Tabs = (() => {
    function activate(tab) {
      const group = tab.closest('.fs-tab-group');
      if (!group) return;
      group.querySelectorAll('.fs-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');

      const target = tab.dataset.tab;
      if (target) {
        const panel = document.getElementById(target);
        const allPanels = document.querySelectorAll(`[data-tab-panel]`);
        const groupPanels = panel?.closest('[data-tab-panels]')
          ?.querySelectorAll('.fs-tab-content') || allPanels;
        groupPanels.forEach(p => p.classList.remove('active'));
        panel?.classList.add('active');
      }

      Events.emit('tabs:change', { tab, target });
    }

    function init() {
      document.addEventListener('click', e => {
        const tab = e.target.closest('.fs-tab');
        if (tab) activate(tab);
      });
    }

    return { activate, init };
  })();

  // ============================================================
  // CONTEXT MENU SYSTEM
  // ============================================================
  class ContextMenu {
    #items = new Map();
    #el = null;

    add(label, callback, opts = {}) {
      this.#items.set(label, { callback, ...opts });
      return this;
    }

    addSeparator() {
      this.#items.set(`__sep_${utils.uid()}`, { separator: true });
      return this;
    }

    show(x, y) {
      this.hide();
      this.#el = utils.el('div', { class: 'fs-context-menu', role: 'menu' });
      this.#el.style.cssText = `position:fixed;left:${x}px;top:${y}px`;

      this.#items.forEach((opts, label) => {
        if (opts.separator) {
          this.#el.append(utils.el('div', { class: 'fs-menu-separator' }));
          return;
        }
        const item = utils.el('div', {
          class: `fs-menu-item${opts.danger ? ' danger' : ''}`,
          role: 'menuitem',
          tabindex: '0',
        });
        item.innerHTML = `${opts.icon ? `<span>${opts.icon}</span>` : ''}<span>${utils.escapeHTML(label)}</span>${opts.shortcut ? `<span class="ms-auto" style="color:var(--muted-2);font-size:0.75rem">${opts.shortcut}</span>` : ''}`;
        item.addEventListener('click', () => { opts.callback(); this.hide(); });
        item.addEventListener('keydown', e => { if (e.key === 'Enter') { opts.callback(); this.hide(); } });
        this.#el.append(item);
      });

      document.body.append(this.#el);

      // Clamp position to viewport
      const rect = this.#el.getBoundingClientRect();
      if (rect.right > window.innerWidth) this.#el.style.left = `${x - rect.width}px`;
      if (rect.bottom > window.innerHeight) this.#el.style.top = `${y - rect.height}px`;
    }

    hide() {
      this.#el?.remove();
      this.#el = null;
    }
  }

  // ============================================================
  // COMMAND PALETTE SYSTEM
  // ============================================================
  const Commands = (() => {
    const registry = new Map();
    let palette = null;
    let filtered = [];
    let highlighted = 0;

    function register(id, opts) {
      registry.set(id, { id, label: opts.label || id, shortcut: opts.shortcut, icon: opts.icon || '›', action: opts.action || opts.callback, group: opts.group });
      return () => registry.delete(id);
    }

    function open() {
      if (palette) return;
      const all = [...registry.values()];
      filtered = all;

      palette = utils.el('div', { class: 'fs-command-palette', role: 'dialog', 'aria-label': 'Command Palette' });
      palette.innerHTML = `
        <input class="fs-command-input" placeholder="Type a command…" aria-label="Search commands" autocomplete="off"/>
        <div class="fs-command-list" role="listbox"></div>
        <div class="fs-command-footer">
          <span><kbd>↑↓</kbd> Navigate</span>
          <span><kbd>↵</kbd> Run</span>
          <span><kbd>Esc</kbd> Close</span>
        </div>`;

      document.body.append(palette);
      const input = palette.querySelector('.fs-command-input');
      input.focus();
      render();

      input.addEventListener('input', e => { filter(e.target.value); });
      input.addEventListener('keydown', handleKeys);
      document.addEventListener('keydown', closeOnEsc);
      document.addEventListener('click', closeOnClickout);
      Events.emit('commands:open');
    }

    function close() {
      palette?.remove();
      palette = null;
      document.removeEventListener('keydown', closeOnEsc);
      document.removeEventListener('click', closeOnClickout);
      Events.emit('commands:close');
    }

    function closeOnEsc(e) { if (e.key === 'Escape') close(); }
    function closeOnClickout(e) { if (palette && !palette.contains(e.target)) close(); }

    function filter(query) {
      const all = [...registry.values()];
      filtered = query
        ? all.filter(c => c.label.toLowerCase().includes(query.toLowerCase()))
        : all;
      highlighted = 0;
      render();
    }

    function render() {
      const list = palette?.querySelector('.fs-command-list');
      if (!list) return;
      list.innerHTML = '';
      if (!filtered.length) {
        list.innerHTML = '<div style="padding:1.5rem;text-align:center;color:var(--muted-3);font-size:0.875rem">No commands found</div>';
        return;
      }
      filtered.forEach((cmd, i) => {
        const item = utils.el('div', {
          class: `fs-command-item${i === highlighted ? ' highlighted' : ''}`,
          role: 'option',
        });
        item.innerHTML = `
          <span class="fs-command-item-icon">${cmd.icon}</span>
          <span>${utils.escapeHTML(cmd.label)}</span>
          ${cmd.shortcut ? `<kbd class="fs-command-item-shortcut">${cmd.shortcut}</kbd>` : ''}`;
        item.addEventListener('click', () => run(cmd));
        list.append(item);
      });
    }

    function handleKeys(e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); highlighted = Math.min(highlighted + 1, filtered.length - 1); render(); }
      if (e.key === 'ArrowUp')   { e.preventDefault(); highlighted = Math.max(highlighted - 1, 0); render(); }
      if (e.key === 'Enter') { e.preventDefault(); if (filtered[highlighted]) run(filtered[highlighted]); }
    }

    function run(cmd) {
      close();
      cmd.action?.();
      Events.emit('commands:run', { id: cmd.id });
    }

    function init() {
      document.addEventListener('keydown', e => {
        if ((e.ctrlKey || e.metaKey) && e.key === 'k') { e.preventDefault(); palette ? close() : open(); }
      });
    }

    return { register, open, close, run, init };
  })();

  // ============================================================
  // LOADING STATE MANAGER
  // ============================================================
  const LoadingState = {
    show(target) {
      const el = typeof target === 'string' ? utils.qs(target) : target;
      el?.classList.add('fs-loading');
    },
    hide(target) {
      const el = typeof target === 'string' ? utils.qs(target) : target;
      el?.classList.remove('fs-loading');
    },
    toggle(target) {
      const el = typeof target === 'string' ? utils.qs(target) : target;
      el?.classList.toggle('fs-loading');
    },
  };

  // ============================================================
  // FORM VALIDATION ENGINE
  // ============================================================
  const Form = (() => {
    const rules = {
      required: (val) => val.trim() !== '' || 'This field is required',
      email:    (val) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val) || 'Please enter a valid email',
      min:      (n)   => (val) => val.length >= n || `Minimum ${n} characters required`,
      max:      (n)   => (val) => val.length <= n || `Maximum ${n} characters allowed`,
      pattern:  (re)  => (val) => re.test(val) || 'Invalid format',
      match:    (sel) => (val) => val === (utils.qs(sel)?.value || '') || 'Values do not match',
      number:   (val) => !isNaN(val) || 'Must be a valid number',
      url:      (val) => { try { new URL(val); return true; } catch { return 'Please enter a valid URL'; } },
      custom:   (fn)  => fn,
    };

    function validate(input, validations = []) {
      for (const v of validations) {
        const rule = typeof v === 'function' ? v : rules[v.type]?.(v.value);
        if (!rule) continue;
        const result = rule(input.value);
        if (result !== true) {
          setError(input, result);
          return false;
        }
      }
      clearError(input);
      return true;
    }

    function setError(input, message) {
      input.classList.add('fs-error');
      input.classList.remove('fs-success');
      input.setAttribute('aria-invalid', 'true');
      const group = input.closest('.fs-form-group');
      if (group) {
        group.classList.add('has-error');
        let msg = group.querySelector('.fs-error-message');
        if (!msg) {
          msg = utils.el('div', { class: 'fs-error-message', role: 'alert' });
          input.after(msg);
        }
        msg.textContent = message;
        msg.style.display = 'block';
      }
    }

    function clearError(input) {
      input.classList.remove('fs-error');
      input.classList.add('fs-success');
      input.setAttribute('aria-invalid', 'false');
      const group = input.closest('.fs-form-group');
      if (group) {
        group.classList.remove('has-error');
        const msg = group.querySelector('.fs-error-message');
        if (msg) { msg.style.display = 'none'; msg.textContent = ''; }
      }
    }

    function validateForm(form) {
      let valid = true;
      utils.qsa('input[data-validate], textarea[data-validate], select[data-validate]', form).forEach(input => {
        try {
          const rules = JSON.parse(input.dataset.validate);
          if (!validate(input, rules)) valid = false;
        } catch {}
      });
      return valid;
    }

    function init() {
      document.addEventListener('blur', e => {
        const input = e.target;
        if (input.dataset.validate) {
          try {
            const v = JSON.parse(input.dataset.validate);
            validate(input, v);
          } catch {}
        }
      }, true);
    }

    return { validate, validateForm, setError, clearError, rules, init };
  })();

  // ============================================================
  // TABLE ENGINE
  // ============================================================
  class Table {
    #el;
    #data;
    #cols;
    #opts;
    #state = { sort: null, dir: 'asc', filter: '', page: 1 };

    constructor(selector, data, cols, opts = {}) {
      this.#el = typeof selector === 'string' ? utils.qs(selector) : selector;
      this.#data = data;
      this.#cols = cols;
      this.#opts = { pageSize: 10, searchable: true, paginate: true, sortable: true, ...opts };
      this.render();
    }

    #filtered() {
      let d = [...this.#data];
      if (this.#state.filter) {
        const q = this.#state.filter.toLowerCase();
        d = d.filter(row => this.#cols.some(c => String(row[c.key] ?? '').toLowerCase().includes(q)));
      }
      if (this.#state.sort) {
        d.sort((a, b) => {
          const va = a[this.#state.sort], vb = b[this.#state.sort];
          return (va < vb ? -1 : va > vb ? 1 : 0) * (this.#state.dir === 'asc' ? 1 : -1);
        });
      }
      return d;
    }

    #paged(d) {
      if (!this.#opts.paginate) return d;
      const ps = this.#opts.pageSize;
      return d.slice((this.#state.page - 1) * ps, this.#state.page * ps);
    }

    render() {
      if (!this.#el) return;
      const filtered = this.#filtered();
      const paged = this.#paged(filtered);
      const totalPages = Math.ceil(filtered.length / this.#opts.pageSize);

      const thead = this.#cols.map(c => {
        const sorted = this.#state.sort === c.key;
        const dir = sorted ? (this.#state.dir === 'asc' ? '↑' : '↓') : '';
        return `<th data-col="${c.key}" class="${sorted ? 'sorted' : ''}">${utils.escapeHTML(c.label)} <span class="sort-icon">${dir}</span></th>`;
      }).join('');

      const tbody = paged.map(row =>
        `<tr>${this.#cols.map(c => `<td>${c.render ? c.render(row[c.key], row) : utils.escapeHTML(String(row[c.key] ?? ''))}</td>`).join('')}</tr>`
      ).join('') || `<tr><td colspan="${this.#cols.length}" style="text-align:center;padding:2rem;color:var(--muted-3)">No data</td></tr>`;

      let pagination = '';
      if (this.#opts.paginate && totalPages > 1) {
        const prev = this.#state.page > 1 ? `<button class="fs-page-btn" data-page="${this.#state.page - 1}">‹</button>` : `<button class="fs-page-btn" disabled>‹</button>`;
        const next = this.#state.page < totalPages ? `<button class="fs-page-btn" data-page="${this.#state.page + 1}">›</button>` : `<button class="fs-page-btn" disabled>›</button>`;
        const pages = Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
          const p = i + 1;
          return `<button class="fs-page-btn${p === this.#state.page ? ' active' : ''}" data-page="${p}">${p}</button>`;
        }).join('');
        pagination = `<div class="fs-pagination"><span>${filtered.length} results</span><div class="fs-pagination-controls">${prev}${pages}${next}</div></div>`;
      }

      let search = '';
      if (this.#opts.searchable) {
        search = `<div style="padding:var(--s-4);border-bottom:1px solid var(--border)"><input class="fs-input fs-table-search" placeholder="Search…" value="${utils.escapeHTML(this.#state.filter)}" style="max-width:280px"></div>`;
      }

      this.#el.innerHTML = `
        <div class="fs-table-wrapper">
          ${search}
          <table class="fs-table">
            <thead><tr>${thead}</tr></thead>
            <tbody>${tbody}</tbody>
          </table>
          ${pagination}
        </div>`;

      this.#bindEvents();
    }

    #bindEvents() {
      this.#el.querySelector('.fs-table-search')?.addEventListener('input', utils.debounce(e => {
        this.#state.filter = e.target.value;
        this.#state.page = 1;
        this.render();
      }, 200));

      this.#el.querySelectorAll('th[data-col]').forEach(th => {
        if (!this.#opts.sortable) return;
        th.style.cursor = 'pointer';
        th.addEventListener('click', () => {
          const col = th.dataset.col;
          this.#state.dir = this.#state.sort === col && this.#state.dir === 'asc' ? 'desc' : 'asc';
          this.#state.sort = col;
          this.render();
        });
      });

      this.#el.querySelectorAll('.fs-page-btn[data-page]').forEach(btn => {
        btn.addEventListener('click', () => {
          this.#state.page = +btn.dataset.page;
          this.render();
        });
      });
    }

    setData(data) { this.#data = data; this.#state.page = 1; this.render(); }
    refresh() { this.render(); }
  }

  // ============================================================
  // CHART WRAPPER (Chart.js integration layer)
  // ============================================================
  const Chart = (() => {
    const accent = '#7c6af7';
    const colors = ['#7c6af7', '#e06cf7', '#f7c66c', '#4dffc3', '#ff6c8e', '#6cc7f7'];

    const defaults = {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: { color: '#c0c0d8', font: { family: "'Instrument Sans', sans-serif", size: 12 }, padding: 20 },
        },
        tooltip: {
          backgroundColor: '#1e1e28',
          borderColor: '#32324a',
          borderWidth: 1,
          titleColor: '#fafaff',
          bodyColor: '#a0a0c0',
          padding: 12,
          cornerRadius: 8,
        },
      },
      scales: {
        x: {
          grid: { color: 'rgba(255,255,255,0.04)' },
          ticks: { color: '#8888b8', font: { family: "'DM Mono', monospace", size: 11 } },
          border: { color: '#32324a' },
        },
        y: {
          grid: { color: 'rgba(255,255,255,0.04)' },
          ticks: { color: '#8888b8', font: { family: "'DM Mono', monospace", size: 11 } },
          border: { color: '#32324a' },
        },
      },
    };

    function create(selector, type, data, opts = {}) {
      const canvas = typeof selector === 'string' ? utils.qs(selector) : selector;
      if (!canvas || !window.Chart) {
        console.warn('FineStyle.Chart: Chart.js not loaded. Include it before calling FineStyle.Chart.create()');
        return null;
      }

      const config = {
        type,
        data: {
          ...data,
          datasets: (data.datasets || []).map((ds, i) => ({
            borderColor: colors[i % colors.length],
            backgroundColor: type === 'line'
              ? `${colors[i % colors.length]}22`
              : colors.map(c => `${c}cc`),
            borderWidth: 2,
            pointRadius: 4,
            pointHoverRadius: 6,
            tension: 0.4,
            fill: type === 'area' ? true : ds.fill,
            ...ds,
          })),
        },
        options: utils.deepMerge(defaults, opts),
      };

      if (type === 'area') config.type = 'line';
      return new window.Chart(canvas, config);
    }

    return {
      create,
      line:    (sel, data, opts) => create(sel, 'line', data, opts),
      bar:     (sel, data, opts) => create(sel, 'bar', data, opts),
      pie:     (sel, data, opts) => create(sel, 'pie', data, { ...opts, scales: undefined }),
      doughnut:(sel, data, opts) => create(sel, 'doughnut', data, { ...opts, scales: undefined }),
      area:    (sel, data, opts) => create(sel, 'area', data, opts),
      colors,
    };
  })();

  // ============================================================
  // TERMINAL INTERFACE
  // ============================================================
  class Terminal {
    #el;
    #body;
    #history = [];
    #histIdx = -1;
    #commands = new Map();
    #opts;

    constructor(selector, opts = {}) {
      this.#el = typeof selector === 'string' ? utils.qs(selector) : selector;
      this.#opts = { prompt: '$', welcomeMsg: 'FineStyle Terminal v3.0', ...opts };
      if (this.#el) this.#build();
    }

    #build() {
      this.#el.innerHTML = `
        <div class="fs-terminal">
          <div class="fs-terminal-header">
            <div class="fs-terminal-controls">
              <div class="fs-code-window-control close"></div>
              <div class="fs-code-window-control min"></div>
              <div class="fs-code-window-control max"></div>
            </div>
            <span class="fs-terminal-title">Terminal</span>
          </div>
          <div class="fs-terminal-body">
            <div class="fs-terminal-output" style="margin-bottom:var(--s-2)">${this.#opts.welcomeMsg}</div>
            <div class="fs-terminal-input-line">
              <span class="fs-terminal-prompt">${this.#opts.prompt}</span>
              <span id="fs-term-input-${this.#uid()}" contenteditable="true" spellcheck="false" style="flex:1;outline:none;color:var(--text-1);min-width:1px;caret-color:var(--accent)"></span>
              <span class="fs-terminal-cursor"></span>
            </div>
          </div>
        </div>`;
      this.#body = this.#el.querySelector('.fs-terminal-body');
      const inputEl = this.#body.querySelector('[contenteditable]');
      inputEl?.addEventListener('keydown', e => this.#handleInput(e, inputEl));
    }

    #uid() { return utils.uid(); }

    #handleInput(e, input) {
      if (e.key === 'Enter') {
        e.preventDefault();
        const cmd = input.textContent.trim();
        input.textContent = '';
        if (cmd) {
          this.#history.unshift(cmd);
          this.#histIdx = -1;
          this.print(`<span class="fs-terminal-prompt">${this.#opts.prompt}</span> ${utils.escapeHTML(cmd)}`);
          this.#run(cmd);
        }
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        this.#histIdx = Math.min(this.#histIdx + 1, this.#history.length - 1);
        input.textContent = this.#history[this.#histIdx] || '';
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        this.#histIdx = Math.max(this.#histIdx - 1, -1);
        input.textContent = this.#histIdx >= 0 ? this.#history[this.#histIdx] : '';
      }
    }

    #run(cmd) {
      const [name, ...args] = cmd.split(' ');
      if (this.#commands.has(name)) {
        const result = this.#commands.get(name)(args);
        if (result) this.print(result);
      } else if (name === 'clear') {
        this.clear();
      } else if (name === 'help') {
        const cmds = [...this.#commands.keys()].join(', ') || 'No custom commands';
        this.print(`Available: clear, help, ${cmds}`, 'output');
      } else {
        this.print(`command not found: ${utils.escapeHTML(name)}`, 'error');
      }
    }

    print(text, type = 'output') {
      const line = utils.el('div', { class: `fs-terminal-${type}` });
      line.innerHTML = text;
      const inputLine = this.#body?.querySelector('.fs-terminal-input-line');
      inputLine ? this.#body.insertBefore(line, inputLine) : this.#body?.append(line);
      this.#body?.scrollTo(0, this.#body.scrollHeight);
    }

    register(name, fn) { this.#commands.set(name, fn); return this; }
    clear() { utils.qsa('.fs-terminal-output, .fs-terminal-success, .fs-terminal-error', this.#body).forEach(l => l.remove()); }
  }

  // ============================================================
  // SCROLLSPY
  // ============================================================
  const Scrollspy = {
    init(sections = 'section', navItems = '.fs-nav-item', offset = 80) {
      const sels = utils.qsa(sections);
      const items = utils.qsa(navItems);
      if (!sels.length || !items.length) return;

      const update = utils.throttle(() => {
        let current = '';
        sels.forEach(s => {
          if (window.scrollY >= s.offsetTop - offset) current = s.id;
        });
        items.forEach(item => {
          item.classList.remove('active');
          if (current && item.getAttribute('href')?.includes(current)) item.classList.add('active');
        });
      }, 100);

      window.addEventListener('scroll', update, { passive: true });
      update();
    },
  };

  // ============================================================
  // SMOOTH SCROLL
  // ============================================================
  const SmoothScroll = {
    to(target, offset = 72) {
      const el = typeof target === 'string' ? utils.qs(target) : target;
      if (!el) return;
      const top = el.getBoundingClientRect().top + window.scrollY - offset;
      window.scrollTo({ top, behavior: 'smooth' });
    },
    init(selector = 'a[href^="#"]', offset = 72) {
      utils.qsa(selector).forEach(a => {
        a.addEventListener('click', e => {
          const target = a.getAttribute('href');
          if (!target || target === '#') return;
          e.preventDefault();
          this.to(target, offset);
          history.pushState(null, '', target);
        });
      });
    },
  };

  // ============================================================
  // COMPONENT REGISTRAR
  // ============================================================
  const registerComponent = (name, config) => {
    const tagName = `fs-${name}`;
    if (customElements.get(tagName)) return;
    customElements.define(tagName, class extends HTMLElement {
      constructor() { super(); config.constructor?.(this); }
      connectedCallback() { config.onMount?.(this); }
      disconnectedCallback() { config.onUnmount?.(this); }
      attributeChangedCallback(n, o, v) { config.onAttrChange?.(this, n, o, v); }
      static get observedAttributes() { return config.observedAttributes || []; }
    });
  };

  // ============================================================
  // GLOBAL INIT
  // ============================================================
  function init() {
    // Start subsystems
    Commands.init();
    Dropdown.init();
    Accordion.init();
    Tabs.init();
    Form.init();
    Animate.scrollReveal();
    SmoothScroll.init();

    // Side nav toggle
    const menuToggle = utils.qs('#menu-toggle, .menu-toggle');
    const sideNav = utils.qs('#side-nav');
    const sideNavOverlay = utils.qs('#side-nav-overlay');
    const sideNavClose = utils.qsa('[data-close-side-nav]');

    if (menuToggle && sideNav) {
      const setSideNav = (open) => {
        sideNav.classList.toggle('active', open);
        sideNavOverlay?.classList.toggle('active', open);
        document.body.classList.toggle('fs-side-nav-open', open && utils.isMobile());
        menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        sideNav.setAttribute('aria-hidden', open ? 'false' : 'true');
      };

      menuToggle.addEventListener('click', e => {
        e.stopPropagation();
        setSideNav(!sideNav.classList.contains('active'));
      });

      sideNavClose.forEach(btn => btn.addEventListener('click', () => setSideNav(false)));
      sideNavOverlay?.addEventListener('click', () => setSideNav(false));
      utils.qsa('#side-nav a[href]').forEach(link => link.addEventListener('click', () => setSideNav(false)));

      document.addEventListener('keydown', e => {
        if (e.key === 'Escape' && sideNav.classList.contains('active')) setSideNav(false);
      });

      document.addEventListener('click', e => {
        if (!sideNav.contains(e.target) && !menuToggle.contains(e.target)) setSideNav(false);
      });

      window.addEventListener('resize', utils.debounce(() => {
        if (!utils.isMobile()) document.body.classList.remove('fs-side-nav-open');
      }, 120));
    }

    // ARIA for existing context menus
    utils.qsa('.fs-context-menu').forEach(m => m.setAttribute('role', 'menu'));
    utils.qsa('.fs-menu-item').forEach(i => i.setAttribute('role', 'menuitem'));

    // Image alt fallback
    utils.qsa('img:not([alt])').forEach(img => img.setAttribute('alt', ''));

    // Register default commands
    Commands.register('toggle-theme', { label: 'Toggle Theme', icon: '◐', shortcut: '⌃T', action: () => Theme.toggle() });
    Commands.register('go-to-top', { label: 'Scroll to Top', icon: '↑', action: () => window.scrollTo({ top: 0, behavior: 'smooth' }) });
    Commands.register('copy-url', { label: 'Copy Current URL', icon: '⊕', action: async () => { await utils.copyToClipboard(location.href); Toast.success('URL copied!'); } });

    // Feather icons compat
    if (typeof feather !== 'undefined') feather.replace();

    // Resize event
    window.addEventListener('resize', utils.debounce(() => {
      Events.emit('fs:resize', { width: window.innerWidth, height: window.innerHeight });
    }, 150));

    Events.emit('fs:ready');
    document.dispatchEvent(new Event('fs-init'));
    console.log('%cFineStyle 3.0%c ready', 'color:#7c6af7;font-weight:700;font-family:serif', 'color:#8888b8');
  }

  document.addEventListener('DOMContentLoaded', () => {
    window.FineStyle = pub;
    init();
  });

  // ============================================================
  // PUBLIC API
  // ============================================================
  const pub = {
    // Meta
    version: '3.0.0',

    // Core systems
    Store, AppStore, Events, Theme, Animate,
    animate, // v2 compat

    // UI Components
    Modal, Toast, Terminal, Table,
    ContextMenu,

    // Subsystems
    Commands, Dropdown, Accordion, Tabs,
    Form, Chart, Scrollspy, SmoothScroll,
    LoadingState,

    // Utilities
    utils,
    registerComponent,

    // Convenience shorthands
    toggleTheme: () => Theme.toggle(),
    setTheme:    (t) => Theme.set(t),

    // v2 compat aliases
    ContextMenuSystem: ContextMenu,
  };

  return pub;
})();

// Expose globally
window.FineStyle = FineStyle;

// v2 backwards compat
window.addEventListener('resize', FineStyle.utils.debounce(() => {
  document.dispatchEvent(new Event('fs-resize'));
}, 150));
